declare namespace SigApi {
    interface ProjectInfo {
        readonly rtVersion: string
        readonly rtDBGVersion: string
        readonly rtBuildNumber: number
        readonly dsVersion: string
        readonly dsBuildNumber: number
        readonly dsPrjName: string
        readonly dsPrjCrc: number
        readonly lvdVersion: string
        readonly lvdPrjName: string
        readonly lvdPrjRevision: string
        readonly lvdPrjRTVersion: string
        readonly lvdPrjDesignerRTVersion: string
        /**
         * Returns the Runtime version
         * 
         * @returns {string} The Runtime version
         */
        getRTVersion(): string
        /**
         * Returns the Runtime debug version
         * 
         * @returns {string} The Runtime debug version
         */
        getRTDebugVersion(): string
        /**
         * Returns the Runtime build number
         * 
         * @returns {number} The Runtime build number
         */
        getRTBuildNumber(): number
        /**
         * Returns the DataService version
         * 
         * @returns {string} The DataService version
         */
        getDSVersion(): string
        /**
         * Returns the DataService build number
         * 
         * @returns {number} The DataService build number
         */
        getDSBuildNumber(): number
        /**
         * Returns the name of the project (from DataService)
         * 
         * @returns {string} The name of the project
         */
        getDSProjectName(): string
        /**
         * Returns the CRC of the project (from DataService)
         * 
         * @returns {number} The CRC of the project
         */
        getDSProjectCRC(): number
        /**
         * Returns the LASAL VISUDesigner version
         * 
         * @returns {string} The LASAL VISUDesigner version
         */
        getLVDVersion(): string
        /**
         * Returns the name of the project (from LASAL VISUDesigner)
         * 
         * @returns {string} The name of the project
         */
        getLVDProjectName(): string
        /**
         * Returns the revision of the project
         * 
         * @returns {string} The revision of the project
         */
        getLVDProjectRevision(): string
        /**
         * Returns the Runtime version of the project
         * 
         * @returns {string} The Runtime version of the project
         */
        getProjectRTVersion(): string
        /**
         * Returns the LASAL VISUDesigner Runtime version of the project
         * 
         * @returns {string} The LASAL VISUDesigner Runtime version of the project
         */
        getProjectDesignerRTVersion(): string
    }
}
